    return f"{x // 60:02d}:{x % 60:02d}"


participants = ["Person1", "Person2"]
day_ph = "Day1"
work_ph = ("T8", "T7")

busy = {
    "Person1": {},
    "Person2": {
        day_ph: [
            ("T8", "T1"),
            ("T4", "T3"),
            ("T6", "T2"),
        ]
    },
}

no_after = {
    "Person2": {day_ph: "T5"}
}

day_names = [VALUES[day_ph]]
work_start = to_minutes(VALUES[work_ph[0]])
work_end = to_minutes(VALUES[work_ph[1]])
duration = int(VALUES["D1"])

cutoffs = []
for p in participants:
    if p in no_after and day_ph in no_after[p]:
        cutoffs.append(to_minutes(VALUES[no_after[p][day_ph]]))
cutoff = min(cutoffs) if cutoffs else None


def attempt(require_end_cutoff):
    solver = Optimize()
    day = Int("day")
    start = Int("start")
    end = Int("end")

    solver.add(day == 0)
    solver.add(start >= work_start)
    solver.add(end == start + duration)
    solver.add(end <= work_end)

    for p in participants:
        for bs_ph, be_ph in busy.get(p, {}).get(day_ph, []):
            bs = to_minutes(VALUES[bs_ph])
            be = to_minutes(VALUES[be_ph])
            solver.add(Or(end <= bs, start >= be))

    if cutoff is not None:
        if require_end_cutoff:
            solver.add(end <= cutoff)
        else:
            solver.add(start <= cutoff)

    solver.minimize(start)

    if solver.check() == sat:
        model = solver.model()
        s = model[start].as_long()
        e = model[end].as_long()
        d = day_names[model[day].as_long()]
        return [d, to_hhmm(s), to_hhmm(e)], e

    return None, None


answer, end_minutes = attempt(False)

if answer is None or (cutoff is not None and end_minutes > cutoff):
    answer2, _ = attempt(True)
    if answer2 is not None:
        answer = answer2

if answer is None:
    print([])
