def solve(after_mode):
    solver = Optimize()
    day = Int("day")
    start = Int("start")
    end = Int("end")

    solver.add(day >= 0, day <= 2)
    solver.add(end == start + duration)
    solver.add(start >= work_start)
    solver.add(start <= work_end - duration)

    if after_mode == "end":
        solver.add(Implies(day == 1, end <= t6))
    else:
        solver.add(Implies(day == 1, start <= t6))

    for i, bs, be in busy_intervals:
        solver.add(Implies(day == i, Or(start >= be, end <= bs)))

    is_day1 = If(day == 0, 1, 0)
    solver.minimize(is_day1 * 1000000 + day * 10000 + start)

    if solver.check() == sat:
        m = solver.model()
        d = m[day].as_long()
        s = m[start].as_long()
        e = m[end].as_long()
        return [actual_days[d], to_hhmm(s), to_hhmm(e)]
    return None

